#include <cstdio>
#include <string>
#include <type_traits>

template <typename T>
void describe(const std::string& name) {
    const char* kind = "other";
    if constexpr (std::is_integral_v<T>) {
        kind = "integral";
    } else if constexpr (std::is_floating_point_v<T>) {
        kind = "floating";
    }
    std::printf("%s:%zu:%s\n", name.c_str(), sizeof(T), kind);
}

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 20) return 1;
    for (int i = 0; i < n; i++) {
        char buffer[32];
        if (std::scanf("%31s", buffer) != 1) return 1;
        std::string name(buffer);
        if (name == "int") {
            describe<int>(name);
        } else if (name == "double") {
            describe<double>(name);
        } else if (name == "char") {
            describe<char>(name);
        } else {
            return 1;
        }
    }
    return 0;
}
